display.text:
use sqlx::SqlitePool;

use crate::caldav::types::{CaldavAuthError, CaldavEventResource};

#[derive(Clone)]
pub struct CaldavRepository {
    pool: SqlitePool,
}

impl CaldavRepository {
    pub fn new(pool: SqlitePool) -> Self {
        Self { pool }
    }

    /// Return the stable DAV identity for an event, creating it on first use.
    pub async fn ensure_resource(
        &self,
        calendar_id: i64,
        event_id: i64,
        now: i64,
    ) -> Result<CaldavEventResource, CaldavAuthError> {
        if let Some(resource) = self.resolve_resource(calendar_id, event_id).await? {
            return Ok(resource);
        }
        let uid = uuid::Uuid::new_v4().to_string();
        let resource_name = uuid::Uuid::new_v4().to_string();
        sqlx::query(
            "INSERT INTO caldav_event_resources (
                event_id, calendar_id, uid, resource_name, created_at, updated_at
             ) VALUES (?, ?, ?, ?, ?, ?)",
        )
        .bind(event_id)
        .bind(calendar_id)
        .bind(&uid)
        .bind(&resource_name)
        .bind(now)
        .bind(now)
        .execute(&self.pool)
        .await
        .map_err(|_| CaldavAuthError::Persistence)?;
        self.resolve_resource(calendar_id, event_id)
            .await?
            .ok_or(CaldavAuthError::Persistence)
    }

    pub async fn resolve_resource(
        &self,
        calendar_id: i64,
        event_id: i64,
    ) -> Result<Option<CaldavEventResource>, CaldavAuthError> {
        let row: Option<(i64, i64, String, String)> = sqlx::query_as(
            "SELECT event_id, calendar_id, uid, resource_name
             FROM caldav_event_resources
             WHERE calendar_id = ? AND event_id = ?",
        )
        .bind(calendar_id)
        .bind(event_id)
        .fetch_optional(&self.pool)
        .await
        .map_err(|_| CaldavAuthError::Persistence)?;
        Ok(row.map(
            |(event_id, calendar_id, uid, resource_name)| CaldavEventResource {
                event_id,
                calendar_id,
                uid,
                resource_name,
            },
        ))
    }

    pub async fn resolve_by_name(
        &self,
        calendar_id: i64,
        resource_name: &str,
    ) -> Result<Option<CaldavEventResource>, CaldavAuthError> {
        let row: Option<(i64, i64, String, String)> = sqlx::query_as(
            "SELECT event_id, calendar_id, uid, resource_name
             FROM caldav_event_resources
             WHERE calendar_id = ? AND resource_name = ?",
        )
        .bind(calendar_id)
        .bind(resource_name)
        .fetch_optional(&self.pool)
        .await
        .map_err(|_| CaldavAuthError::Persistence)?;
        Ok(row.map(
            |(event_id, calendar_id, uid, resource_name)| CaldavEventResource {
                event_id,
                calendar_id,
                uid,
                resource_name,
            },
        ))
    }

    /// Create a DAV resource mapping with a client-supplied UID and resource
    /// name. Fails with `ResourceExists` if the name is taken or `UidConflict`
    /// if the UID is already mapped in this calendar.
    pub async fn create_resource(
        &self,
        calendar_id: i64,
        event_id: i64,
        uid: &str,
        resource_name: &str,
        now: i64,
    ) -> Result<CaldavEventResource, CaldavAuthError> {
        if self
            .resolve_by_name(calendar_id, resource_name)
            .await?
            .is_some()
        {
            return Err(CaldavAuthError::ResourceExists);
        }
        let uid_taken: bool = sqlx::query_scalar(
            "SELECT EXISTS(
                SELECT 1 FROM caldav_event_resources WHERE calendar_id = ? AND uid = ?
             )",
        )
        .bind(calendar_id)
        .bind(uid)
        .fetch_one(&self.pool)
        .await
        .map_err(|_| CaldavAuthError::Persistence)?;
        if uid_taken {
            return Err(CaldavAuthError::UidConflict);
        }
        sqlx::query(
            "INSERT INTO caldav_event_resources (
                event_id, calendar_id, uid, resource_name, created_at, updated_at
             ) VALUES (?, ?, ?, ?, ?, ?)",
        )
        .bind(event_id)
        .bind(calendar_id)
        .bind(uid)
        .bind(resource_name)
        .bind(now)
        .bind(now)
        .execute(&self.pool)
        .await
        .map_err(|_| CaldavAuthError::Persistence)?;
        self.resolve_by_name(calendar_id, resource_name)
            .await?
            .ok_or(CaldavAuthError::Persistence)
    }

    /// Event IDs currently exposed by this slice: timed, non-recurring events
    /// that still exist in the calendar. Callers ensure a stable resource
    /// mapping for each before serializing.
    pub async fn list_exposed_event_ids(
        &self,
        calendar_id: i64,
    ) -> Result<Vec<i64>, CaldavAuthError> {
        let ids: Vec<i64> = sqlx::query_scalar(
            "SELECT id FROM events
              WHERE calendar_id = ?
                AND event_kind = 'timed'
                AND recurrence_rule IS NULL
              ORDER BY id",
        )
        .bind(calendar_id)
        .fetch_all(&self.pool)
        .await
        .map_err(|_| CaldavAuthError::Persistence)?;
        Ok(ids)
    }

    /// Event IDs that overlap the given UTC time range, bounded by `limit`.
    pub async fn list_events_in_range(
        &self,
        calendar_id: i64,
        start_utc: i64,
        end_utc: i64,
        limit: usize,
    ) -> Result<Vec<i64>, CaldavAuthError> {
        let ids: Vec<i64> = sqlx::query_scalar(
            "SELECT id FROM events
              WHERE calendar_id = ?
                AND event_kind = 'timed'
                AND recurrence_rule IS NULL
                AND timed_start_utc < ?
                AND timed_end_utc > ?
              ORDER BY id
              LIMIT ?",
        )
        .bind(calendar_id)
        .bind(end_utc)
        .bind(start_utc)
        .bind(limit as i64)
        .fetch_all(&self.pool)
        .await
        .map_err(|_| CaldavAuthError::Persistence)?;
        Ok(ids)
    }
}

